// 音声メモ: トリガーデータと文字起こし結果を統合
const msg = $('Telegram Trigger').first().json.message;
const geminiResp = $input.first().json;

let transcribed = '';
try {
  transcribed = geminiResp.candidates[0].content.parts[0].text.trim();
} catch (e) {
  transcribed = '[文字起こし失敗]';
}

return [{
  json: {
    chat_id: msg.chat.id,
    message_id: msg.message_id,
    member_name: msg.from.first_name || msg.from.username || 'unknown',
    raw_text: transcribed,
    source_type: 'voice'
  }
}];

// テキストメモ
const msg = $json.message;
return [{
  json: {
    chat_id: msg.chat.id,
    message_id: msg.message_id,
    member_name: msg.from.first_name || msg.from.username || 'unknown',
    raw_text: msg.text,
    source_type: 'text'
  }
}];

