// Gemini分類結果をパースしてNocoDB保存用データを構築
const memo = $('Prepare Voice Memo').first()?.json || $('Prepare Text Memo').first()?.json;
const geminiResp = $input.first().json;

let classify = { category: 'タグなし', mentioned_customer: '', mentioned_project: '', tags: [], confidence: 'low' };
try {
  const text = geminiResp.candidates[0].content.parts[0].text;
  const cleaned = text.replace(/```json|```/g, '').trim();
  classify = JSON.parse(cleaned);
} catch (e) {
  // パース失敗時はデフォルト値
}

return [{
  json: {
    created_at: new Date().toISOString(),
    member_name: memo.member_name,
    telegram_chat_id: memo.chat_id,
    telegram_message_id: memo.message_id,
    raw_text: memo.raw_text,
    original_transcription: memo.raw_text,
    source_type: memo.source_type,
    category: classify.category || 'タグなし',
    mentioned_customer: classify.mentioned_customer || '',
    mentioned_project: classify.mentioned_project || '',
    tags: Array.isArray(classify.tags) ? classify.tags.join(',') : '',
    confidence: classify.confidence || 'low',
    edited: false,
    deleted: false,
    processed: false
  }
}];

// フィードバックメッセージ作成
const rec = $('Build NocoDB Record').first().json;
const nocoResp = $input.first().json;
const memoId = nocoResp.memo_id || nocoResp.Id || nocoResp.id || '?';

const time = new Date(rec.created_at).toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit', timeZone: 'Asia/Tokyo' });
const mark = rec.confidence === 'low' ? '?' : '';
const preview = rec.raw_text.length > 200 ? rec.raw_text.substring(0, 200) + '...' : rec.raw_text;

const tags = [];
if (rec.category) tags.push(`カテゴリ: ${rec.category}${mark}`);
if (rec.mentioned_customer) tags.push(`顧客: ${rec.mentioned_customer}`);
if (rec.mentioned_project) tags.push(`案件: ${rec.mentioned_project}`);
if (rec.tags) tags.push(`タグ: ${rec.tags}`);

const label = rec.source_type === 'voice' ? '文字起こし結果' : '本文';
const message = `📝 メモを保存しました (${time}) [ID:${memoId}]\n\n▼ ${label}\n${preview}\n\n▼ 推定\n${tags.join(' / ') || '(タグなし)'}\n\n修正: 「修正: 内容」\n削除: 「削除 ${memoId}」`;

return [{ json: { chat_id: rec.telegram_chat_id, message } }];

// コマンドパーサー（修正/削除/上書き）
const text = $json.message.text;
const chatId = $json.message.chat.id;

let command = null;
let target_memo_id = null;
let payload = null;

const delMatch = text.match(/^削除\s+(\d+)/);
const editMatch = text.match(/^修正(?:\s+(\d+))?[:：]\s*(.+)/s);
const overwriteMatch = text.match(/^上書き(?:\s+(\d+))?[:：]\s*(.+)/s);

if (delMatch) {
  command = 'delete';
  target_memo_id = parseInt(delMatch[1]);
} else if (overwriteMatch) {
  command = 'overwrite';
  target_memo_id = overwriteMatch[1] ? parseInt(overwriteMatch[1]) : null;
  payload = overwriteMatch[2];
} else if (editMatch) {
  command = 'edit';
  target_memo_id = editMatch[1] ? parseInt(editMatch[1]) : null;
  payload = editMatch[2];
}

return [{ json: { command, target_memo_id, payload, chat_id: chatId } }];

// コマンド処理: 更新内容を構築
const cmd = $('Parse Command').first().json;
const target = $input.first().json;
const memoId = cmd.target_memo_id || target.memo_id || target.Id || target.id;

let update = {};
let feedback = '';

if (cmd.command === 'delete') {
  update = { deleted: true };
  feedback = `🗑 メモ ID:${memoId} を削除しました`;
} else if (cmd.command === 'overwrite') {
  update = { raw_text: cmd.payload, edited: true, edited_at: new Date().toISOString() };
  feedback = `✅ メモ ID:${memoId} を上書きしました\n\n${cmd.payload}`;
} else if (cmd.command === 'edit') {
  const newText = (target.raw_text || '') + '\n[修正] ' + cmd.payload;
  update = { raw_text: newText, edited: true, edited_at: new Date().toISOString() };
  feedback = `✏️ メモ ID:${memoId} に修正を追記\n\n${newText}`;
}

return [{ json: { memo_id: memoId, update, chat_id: cmd.chat_id, feedback } }];
